mapper.select:
select count(1)task_count,task_type from wms_tasks t
where 1=1

    and DATE(t.create_time) = #{createTimeString}


    and t.task_status = #{taskStatus}



    and t.target_warehouse_id = #{targetWarehouseId}



    and t.source_warehouse_id = #{sourceWarehouseId}


group by t.task_type

select
month(t.create_time) as month,
count(1) as count
from wms_stock_in_orders t
where t.create_time >= #{startTime}
and t.create_time < #{endTime}

    and t.warehouse_id = #{warehouseId}

group by month(t.create_time)
order by month(t.create_time)

select
month(t.create_time) as month,
count(1) as count
from wms_out_orders t
where t.create_time >= #{startTime}
and t.create_time < #{endTime}

    and t.warehouse_id = #{warehouseId}

group by month(t.create_time)
order by month(t.create_time)

select p.owner_id as ownerId, co.owner_name as ownerName, sum(ifnull(i.packed_quantity, 0)) as totalQuantity from wms_out_orders_items i left join wms_out_orders o on i.order_id = o.id left join wms_products p on i.sku_id = p.id left join wms_cargo_owners co on p.owner_id = co.id where ifnull(i.packed_quantity, 0) > 0
and o.warehouse_id = #{warehouseId}
group by p.owner_id, co.owner_name order by totalQuantity desc limit 5
